<?php
require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();$message='';$error='';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';
 if($a==='add_project'){$name=trim($_POST['name']??'');$budget=parse_amount_ro($_POST['budget']??'0');if(!$name)throw new RuntimeException('Completează denumirea renovării.');$pdo->prepare('INSERT INTO house_renovations(name,budget,status,notes,created_by_member_id) VALUES(?,?,?,?,?)')->execute([$name,$budget,'planned',trim($_POST['notes']??'')?:null,$memberId]);$message='Renovarea a fost creată.';}
 if($a==='update_project'){$pid=(int)$_POST['id'];$name=trim($_POST['name']??'');$budget=parse_amount_ro($_POST['budget']??'0');$status=$_POST['status']??'planned';if(!in_array($status,['planned','active','done'],true))$status='planned';$pdo->prepare('UPDATE house_renovations SET name=?,budget=?,status=?,notes=? WHERE id=?')->execute([$name,$budget,$status,trim($_POST['notes']??'')?:null,$pid]);$message='Renovarea a fost actualizată.';$id=$pid;}
 if($a==='delete_project'){$pid=(int)$_POST['id'];$pdo->prepare('DELETE FROM house_renovations WHERE id=?')->execute([$pid]);header('Location:/renovations.php');exit;}
 if($a==='add_cost'){$pid=(int)$_POST['renovation_id'];$name=trim($_POST['name']??'');$amount=parse_amount_ro($_POST['amount']??'0');$date=parse_ro_date($_POST['cost_date']??'',date('Y-m-d'));$due=parse_ro_date($_POST['due_date']??'');$paid=!empty($_POST['paid'])?1:0;if(!$name||$amount<=0)throw new RuntimeException('Completează denumirea și suma.');$pdo->prepare('INSERT INTO house_renovation_costs(renovation_id,name,amount,paid,cost_date,due_date,notes,created_by_member_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$pid,$name,$amount,$paid,$date?:date('Y-m-d'),$due,trim($_POST['notes']??'')?:null,$memberId]);$message=$paid?'Cheltuiala a fost adăugată.':'Costul planificat a fost adăugat.';$id=$pid;}
 if($a==='toggle_paid'){$cid=(int)$_POST['id'];$pid=(int)$_POST['renovation_id'];$pdo->prepare('UPDATE house_renovation_costs SET paid=IF(paid=1,0,1),cost_date=IF(paid=0,CURDATE(),cost_date) WHERE id=? AND renovation_id=?')->execute([$cid,$pid]);$id=$pid;}
 if($a==='delete_cost'){$cid=(int)$_POST['id'];$pid=(int)$_POST['renovation_id'];$pdo->prepare('DELETE FROM house_renovation_costs WHERE id=? AND renovation_id=?')->execute([$cid,$pid]);$message='Costul a fost șters.';$id=$pid;}
}catch(Throwable $e){$error=$e->getMessage();}}
if($id){$q=$pdo->prepare('SELECT r.*,COALESCE(SUM(CASE WHEN c.paid=1 THEN c.amount ELSE 0 END),0) spent,COALESCE(SUM(CASE WHEN c.paid=0 THEN c.amount ELSE 0 END),0) planned FROM house_renovations r LEFT JOIN house_renovation_costs c ON c.renovation_id=r.id WHERE r.id=? GROUP BY r.id');$q->execute([$id]);$project=$q->fetch();if(!$project)$id=0;}
$pageTitle=$id?'Renovare':'Renovări';$active='more';$backUrl=$id?'/renovations.php':'/home.php';require __DIR__.'/includes/layout_top.php';?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<?php if(!$id):$projects=$pdo->query('SELECT r.*,COALESCE(SUM(CASE WHEN c.paid=1 THEN c.amount ELSE 0 END),0) spent,COALESCE(SUM(CASE WHEN c.paid=0 THEN c.amount ELSE 0 END),0) planned_costs FROM house_renovations r LEFT JOIN house_renovation_costs c ON c.renovation_id=r.id GROUP BY r.id ORDER BY FIELD(r.status,"active","planned","done"),r.id DESC')->fetchAll();?><section class="hero-card subtle"><div><h2>Renovările casei</h2><p>Bugete speciale pentru casă, separate de bugetul familiei.</p></div><button class="btn primary small" data-open-sheet="renSheet"><?=icon('plus')?> Renovare</button></section><div class="renovation-grid"><?php foreach($projects as $r):$remaining=(float)$r['budget']-(float)$r['spent'];$pct=$r['budget']>0?min(100,round($r['spent']/$r['budget']*100)):0;?><a class="renovation-card" href="/renovations.php?id=<?=$r['id']?>"><div><span class="mini-icon amber"><?=icon('hammer')?></span><b><?=e($r['name'])?></b><small><?=e($r['status']==='done'?'Finalizată':($r['status']==='active'?'În lucru':'Planificată'))?></small></div><div class="renovation-numbers"><span>Buget <b><?=money_ro($r['budget'])?></b></span><span>Plătit <b><?=money_ro($r['spent'])?></b></span><span class="<?=$remaining<0?'neg':'pos'?>">Rămas <b><?=money_ro($remaining)?></b></span></div><?php if((float)$r['planned_costs']>0):?><small class="renovation-planned-note">De plată: <?=money_ro($r['planned_costs'])?></small><?php endif;?><div class="progress"><i style="width:<?=$pct?>%"></i></div></a><?php endforeach;?><?php if(!$projects):?><div class="empty">Nu ai renovări create.</div><?php endif;?></div>
<div class="modal" id="renSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Renovare nouă</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_project"><label>Denumire<input name="name" required placeholder="Ex: Fațadă casă"></label><label>Buget special<input name="budget" inputmode="decimal" placeholder="30000"></label><label>Notițe<textarea name="notes" rows="3"></textarea></label><button class="btn primary wide">Creează renovarea</button></form></section></div>
<?php else:$remaining=(float)$project['budget']-(float)$project['spent'];$afterPlanned=$remaining-(float)$project['planned'];$q=$pdo->prepare('SELECT c.*,m.name creator FROM house_renovation_costs c LEFT JOIN family_members m ON m.id=c.created_by_member_id WHERE c.renovation_id=? ORDER BY c.paid ASC,COALESCE(c.due_date,c.cost_date),c.id DESC');$q->execute([$id]);$costs=$q->fetchAll();?><section class="renovation-hero"><div><span><?=e($project['status']==='done'?'Finalizată':($project['status']==='active'?'În lucru':'Planificată'))?></span><h2><?=e($project['name'])?></h2></div><div class="renovation-summary"><article><span>Buget</span><b><?=money_ro($project['budget'])?></b></article><article><span>Plătit</span><b><?=money_ro($project['spent'])?></b></article><article><span>Rămas</span><b class="<?=$remaining<0?'neg':'pos'?>"><?=money_ro($remaining)?></b></article></div><?php if((float)$project['planned']>0):?><div class="renovation-planned-summary"><span>Costuri viitoare</span><b><?=money_ro($project['planned'])?></b><small>După ele ar rămâne <strong class="<?=$afterPlanned<0?'neg':'pos'?>"><?=money_ro($afterPlanned)?></strong></small></div><?php endif;?><?php if($remaining<0):?><p class="over-budget-note">Buget depășit cu <?=money_ro(abs($remaining))?>.</p><?php endif;?></section><div class="renovation-primary-actions"><button class="btn primary" data-open-sheet="costSheet"><?=icon('plus')?> <span>Adaugă cost</span></button><button class="btn soft" data-open-sheet="editRenSheet"><?=icon('edit')?> <span>Editează renovarea</span></button></div><section><div class="section-head"><div><h2>Costuri</h2><p>Plătite și planificate, separat de bugetul familiei.</p></div></div><div class="renovation-cost-list"><?php foreach($costs as $c):?>
<article class="renovation-cost-card <?=$c['paid']?'is-paid':'is-planned'?>">
  <span class="renovation-cost-icon"><?=$c['paid']?icon('hammer'):icon('calendar')?></span>
  <div class="renovation-cost-main">
    <div class="renovation-cost-title"><strong><?=e($c['name'])?></strong><span class="status-pill <?=$c['paid']?'paid':''?>"><?=$c['paid']?'Plătit':'Planificat'?></span></div>
    <div class="renovation-cost-meta">
      <?php if($c['paid']):?><span><?=e(date_ro($c['cost_date']))?></span><?php elseif($c['due_date']):?><span>Scadență <?=e(date_ro($c['due_date']))?></span><?php else:?><span>Fără scadență</span><?php endif;?>
      <?php if($c['creator']):?><span><?=e($c['creator'])?></span><?php endif;?>
    </div>
    <?php if($c['notes']):?><p><?=e($c['notes'])?></p><?php endif;?>
  </div>
  <strong class="renovation-cost-amount <?=$c['paid']?'neg':''?>"><?=$c['paid']?'−':''?><?=money_ro($c['amount'])?></strong>
  <div class="renovation-cost-actions">
    <form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_paid"><input type="hidden" name="id" value="<?=$c['id']?>"><input type="hidden" name="renovation_id" value="<?=$id?>"><button class="btn soft small" type="submit"><?=$c['paid']?'Mută la neplătit':'Marchează plătit'?></button></form>
    <form method="post" onsubmit="return confirm('Ștergi costul?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_cost"><input type="hidden" name="id" value="<?=$c['id']?>"><input type="hidden" name="renovation_id" value="<?=$id?>"><button class="btn ghost small danger" type="submit"><?=icon('trash')?> <span>Șterge</span></button></form>
  </div>
</article>
<?php endforeach;?><?php if(!$costs):?><div class="empty">Nu ai costuri adăugate.</div><?php endif;?></div></section>
<div class="modal" id="costSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Cost renovare</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_cost"><input type="hidden" name="renovation_id" value="<?=$id?>"><label>Denumire<input name="name" required placeholder="Ex: Schelă / materiale"></label><label>Sumă<input name="amount" inputmode="decimal" required></label><label class="check-row"><input type="checkbox" name="paid" value="1" checked><span>Este deja plătit</span></label><label>Data plății<input class="ro-date" name="cost_date" value="<?=date('d.m.Y')?>"></label><label>Scadență / dată estimată<input class="ro-date" name="due_date" placeholder="ZZ.LL.AAAA"></label><label>Notițe<textarea name="notes" rows="3"></textarea></label><button class="btn primary wide">Adaugă costul</button></form></section></div>
<div class="modal" id="editRenSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Editează renovarea</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update_project"><input type="hidden" name="id" value="<?=$id?>"><label>Denumire<input name="name" value="<?=e($project['name'])?>" required></label><label>Buget<input name="budget" inputmode="decimal" value="<?=e($project['budget'])?>"></label><label>Status<select name="status"><option value="planned" <?=$project['status']==='planned'?'selected':''?>>Planificată</option><option value="active" <?=$project['status']==='active'?'selected':''?>>În lucru</option><option value="done" <?=$project['status']==='done'?'selected':''?>>Finalizată</option></select></label><label>Notițe<textarea name="notes" rows="3"><?=e($project['notes'])?></textarea></label><button class="btn primary wide">Salvează</button></form></section></div><?php endif;?>
